  "Every candlestick and chart pattern taught in the school — annotated diagram, the psychology behind it, and how traders typically use it. Open any card for a stepped simulation. Educational only, not advice.": "Cada vela y patrón gráfico enseñado en la escuela — diagrama anotado, la psicología detrás de ella, y cómo los traders lo usan típicamente. Abra cualquier tarjeta para una simulación paso. Sólo educativo, no consejo.",
