  "5 steps": "5 pasos",
  "Every candle compresses open, high, low and close into a body and two wicks. Learn to read that story before chasing patterns.": "Cada vela comprime abierta, alta, baja y cercana a un cuerpo y dos mechas. Aprende a leer esa historia antes de perseguir patrones.",
