  ": each period shows open, high, low and close. Line charts show closes only; OHLC bars show the same four prices without colour fills.": ": cada período muestra abierto, alto, bajo y cerca. Las gráficas de línea sólo muestran cierres; las barras OHLC muestran los mismos cuatro precios sin rellenos de color.",
  "Candles pack OHLC into a shape you can scan quickly. The story is still the same four numbers.": "Las velas empacan OHLC en una forma que puede escanear rápidamente. La historia sigue siendo los mismos cuatro números.",
  "Candles = OHLC with a body and wicks.": "Velas = OHLC con un cuerpo y mechas.",
  "Line charts hide intra-period extremes — fine for big-picture trend, weak for wick rejection.": "Las tablas de líneas ocultan extremos intra-períodos — finos para la tendencia de la gran imagen, débiles para el rechazo de la mecha.",
  "Never mix timeframes without labelling them.": "Nunca mezcle los plazos sin etiquetarlos.",
