  "A pattern name is a nickname for a shape plus a context. A hammer after a decline is not the same story as the identical shape after a rally (hanging man).": "Un nombre de patrón es un apodo para una forma más un contexto. Un martillo después de un declive no es la misma historia que la forma idéntica después de un rallye (hombre ascendente).",
