  "Confirm vs trap": "Confirme vs trampa",
  "Volume estimates how much changed hands. Rising price on rising volume = healthier participation than rising price on dying volume.": "Volumen calcula cuánto cambió las manos. Precio creciente en volumen creciente = participación más saludable que aumento del precio en volumen moribundo.",
  "Breakouts prefer above-average volume.": "Los brotes prefieren un volumen superior al promedio.",
