  "Not found · ": "No se encuentra ·",
  "Learn trading fundamentals by playing: candlesticks, support and resistance, trend lines, chart patterns, Fibonacci, moving averages, indicators, multi-timeframe analysis and risk. Beginner and Advanced tracks with interactive lessons, games and simulations.": "Aprende los fundamentos del trading jugando: velas, soporte y resistencia, líneas de tendencia, patrones gráficos, Fibonacci, medias móviles, indicadores, análisis de varios marcos temporales y gestión del riesgo. Itinerarios de Principiante y Avanzado con lecciones, juegos y simulaciones interactivas.",
  " — interactive ": "— interactivo",
  " in The Trade School: learn to read the market by playing. Educational only, not financial advice.": "en la Escuela de trading: aprender a leer el mercado jugando. Educación sólo, no asesoramiento financiero.",
  "Candlestick and chart-pattern library with annotated diagrams — every pattern explained and shown. Educational only.": "vela y biblioteca de cuadros con diagramas anotados — cada patrón explicado y mostrado. Sólo educativo.",
  "A searchable glossary of 85+ trading terms, from ask price to Wick. Educational only.": "Un glosario de 85+ términos comerciales, desde el precio de pedido a Wick. Sólo educativo.",
  "Trading platforms and tools The Trade School partners with. Some links are affiliate links. Educational only.": "Plataformas de negociación y herramientas La Escuela de trading colabora. Algunos enlaces son enlaces de afiliados. Sólo educativo.",
  "Rule-based chart setups with a checklist, entry, stop and target. Educational only, not financial advice.": "Configuraciones de gráficos basadas en reglas con una lista de verificación, entrada, parada y objetivo. Educación sólo, no asesoramiento financiero.",
  "The Live Market Lab: quotes, market hours and real charts with source and delay labelled. Educational only.": "The Live Market Lab: presupuestos, horarios de mercado y gráficos reales con fuente y retraso etiquetado. Sólo educativo.",
  "Every game in The Trade School — drills for candlesticks, patterns, trends, Fibonacci, risk and more. Educational only.": "Cada juego en la Escuela de trading — simulacros para velas, patrones, tendencias, Fibonacci, riesgo y más. Sólo educativo.",
  "Your progress across both tracks: lessons, games, XP, badges and daily streak. Educational only.": "Tu progreso en ambas pistas: lecciones, juegos, XP, placas y racha diaria. Sólo educativo.",
  "Sign in or create a free account to open the Beginner and Advanced tracks. Educational only.": "Iniciar sesión o crear una cuenta gratuita para abrir las pistas de Beginner y Advanced. Sólo educativo.",
  "Unlock every lesson and game in the Beginner and Advanced tracks. Educational only.": "Desbloquear cada lección y juego en las pistas de principiantes y avanzados. Sólo educativo.",
