  "Ask minus bid; a pip is 0.0001 here.": "Precio vendedor menos comprador; aquí un pip equivale a 0.0001.",
  "Price breaks resistance, retests it from above and holds. The old resistance is now…": "El precio rompe una resistencia, vuelve a probarla desde arriba y se mantiene. La antigua resistencia ahora es...",
