  "Divergent": "Divergente",
  "70 is the upper line.": "70 es la línea superior.",
  "Entry 50, stop 48, target 56. Reward-to-risk?": "Entrada en 50, stop en 48 y objetivo en 56. ¿Cuál es la relación beneficio/riesgo?",
  "Divide the distance to the target by the distance to the stop.": "Divide la distancia al objetivo entre la distancia al stop.",
  "You risk 1% of a $10,000 account with a stop $2 away. How many shares?": "Arriesgas el 1 % de una cuenta de $10,000 y el stop está a $2. ¿Cuántas acciones puedes comprar?",
  "1% of $10,000 is your dollar risk.": "El 1 % de $10,000 es el importe máximo que arriesgas.",
  "Price makes a higher high while RSI makes a lower high. This is…": "El precio marca un máximo ascendente mientras el RSI marca uno descendente. Esto es...",
  "Bearish divergence": "Divergencia bajista",
