  "Little or no upper wick": "Pequeña o ninguna mecha superior",
  "Close sits near the high of the period.": "Cerrar se sienta cerca del alto del período.",
  "Open 100, high 101, low 95, close 96. How long is the upper wick?": "Abierto 100, alto 101, bajo 95, cerca 96. ¿Cuánto dura la mecha superior?",
  "1 point": "1 punto",
  "5 points": "5 puntos",
  "4 points": "4 puntos",
  "6 points": "6 puntos",
  "A candle hides the path inside the period: it does not show whether the high came before the low.": "Una vela esconde el camino dentro del período: no muestra si el alto vino antes del bajo.",
  "Same OHLC can come from very different intra-period paths.": "Mismo OHLC puede venir de diferentes caminos intra-períodos.",
  "Patterns fail — treat candles as evidence, not prophecy.": "Los patrones fallan — tratar las velas como evidencia, no profecía.",
  "Next: build candles yourself in Candle Builder, then learn named patterns.": "Siguiente: construir velas usted mismo en Candle Builder, luego aprender patrones nombrados.",
  "callout callout--tip": "Callout...",
  "On lower timeframes, noise dominates. Many readers prefer daily candles for structure and use intraday only for timing.": "En los plazos inferiores, el ruido domina. Muchos lectores prefieren velas diarias para estructurar y utilizar intradía sólo para el tiempo.",
  "Sellers have been in control: lower highs and lower lows.": "Los vendedores han estado en control: bajos altos y bajos bajos bajos.",
  "Hammer.": "Martillo.",
  "Long lower wick, small body near the high — buyers rejected the lows.": "Mecha larga inferior, pequeño cuerpo cerca del alto — los compradores rechazaron los bajos.",
  "Confirmation.": "Confirmación.",
  "A close above the hammer high is the usual confirmation. Stop goes under the wick.": "Un cierre por encima del martillo alto es la confirmación habitual. Parar debajo de la mecha.",
  "Follow-through is never guaranteed. The stop was placed before the entry for that reason.": "El seguimiento nunca está garantizado. La parada fue colocada antes de la entrada por esa razón.",
  "Watch context → shape → confirmation → outcome.": "Ver contexto → forma → confirmación → resultado.",
  "Messier than textbooks. Look for the same rules, not the same picture.": "Más fácil que los libros de texto. Busca las mismas reglas, no la misma imagen.",
  "Same family, different conviction.": "Misma familia, diferente convicción.",
  "Strong bullish engulfing": "Fuerte bullish engulfing",
  "Engulfing": "Engulfing",
  "After a clear decline": "Después de una clara disminución",
  "Body fully covers prior body": "El cuerpo cubre completamente el cuerpo anterior",
  "Next candle follows through": "La próxima vela sigue a través",
  "Weak lookalike": "Mirador débil",
  "Indecision": "Indecisión",
  "No decisive body takeover": "No es una toma de cuerpo decisiva",
  "Could be a pause, not a reverse": "Podría ser una pausa, no un revés",
  "Do not force a name onto noise": "No forzar un nombre sobre el ruido",
  "After a decline": "Después de una disminución",
  "Downtrend into the candle.": "Métete en la vela.",
  "Lower wick ≥ 2× body": "Mecha inferior ≥ 2× cuerpo",
  "Rejection of lows.": "Rechazo de bajos.",
  "Little upper wick": "Pequeña mecha superior",
  "Close near the high.": "Cerca de lo alto.",
  "After a decline: small body at the top, long lower wick. Name?": "Después de un declive: pequeño cuerpo en la parte superior, larga mecha inferior. ¿Nombre?",
  "Even textbook patterns fail — size risk as if this one will.": "Incluso los patrones de libros de texto fallan — el riesgo de tamaño como si éste lo hiciera.",
  "Combine with level and trend (confluence) later in Advanced.": "Combine con nivel y tendencia (confluencia) más tarde en Advanced.",
  "Drill recognition in Pattern Flash.": "Reconocimiento de perforación en Pattern Flash.",
  "On a short timeframe every wiggle looks important. Zoom out before you decide the trend.": "En un corto período de tiempo cada rejilla parece importante. Acercate antes de decidir la tendencia.",
  "Same market, more context.": "El mismo mercado, más contexto.",
  "Higher highs and higher lows appear once you see enough structure.": "Altos altos y bajos superiores aparecen una vez que vea suficiente estructura.",
  "Pick a timeframe that matches your holding period. Day traders and investors can both be right on different clocks.": "Escoja un plazo que coincida con su período de retención. Los traders y los inversores pueden estar a la derecha en diferentes relojes.",
  "Most traders here use ": "La mayoría de los comerciantes usan aquí",
  "A noisy 5-minute chart can be a clean daily uptrend. Context first.": "Un gráfico ruidoso de 5 minutos puede ser una actualización diaria limpia. Contexto primero.",
  "Linear scale treats a $10 move the same everywhere. Log scale treats equal ": "La escala lineal trata un movimiento de $10 igual en todas partes. Log scale treats equal",
  " moves as equal distance — useful for multi-year or high-growth charts.": "se mueve como distancia igual – útil para gráficos multianuales o de alto crecimiento.",
  "Use linear for short-term price action near current levels.": "Use lineal for short-term price action near current levels.",
  "Use log when comparing large percentage moves across years.": "Utilice el registro al comparar grandes porcentajes se mueve a través de años.",
  "Trend lines drawn on the wrong scale can look “broken” when they are not.": "Las líneas de tendencia dibujadas en la escala equivocada pueden verse “rojadas” cuando no lo están.",
  "This school’s charts are linear by default. When you move to a platform, check the scale toggle before drawing.": "Los gráficos de esta escuela son lineales por defecto. Cuando se mueve a una plataforma, compruebe la escala para cambiar antes de dibujar.",
  "You swing-trade for days to weeks. Which primary chart is usually most appropriate?": "Cambias durante días a semanas. ¿Qué gráfico primario es generalmente más apropiado?",
  "Daily (with a higher timeframe weekly for bias)": "Diario (con un plazo más alto semanal para sesgo)",
  "1-second ticks only": "1 segundo garrapatas sólo",
  "Yearly candles only": "Velas anuales sólo",
  "Any random timeframe is fine": "Cualquier plazo aleatorio está bien",
  "Chart type does not create edge — it only displays price.": "El tipo de gráfico no crea el borde — sólo muestra el precio.",
  "Changing timeframe mid-trade to “make the chart look better” is a common bias.": "Cambiar el cronograma medio para “hacer que el gráfico se vea mejor” es un sesgo común.",
  "Next: candlestick patterns — still just OHLC, with names.": "Siguiente: patrones de vela - todavía sólo OHLC, con nombres.",
  "Quiet tape before the impulse.": "Cinta tranquila antes del impulso.",
  "The pole.": "El poste.",
  "A fast one-way rally — the measured-move reference.": "Un rallye de un solo sentido rápido — la referencia de medición.",
  "The flag.": "La bandera.",
  "Gentle counter-drift on lighter volume.": "Gentil contra-reductor en volumen más ligero.",
  "Breakout.": "Breakout.",
  "Close above the flag; stop under the flag low.": "Cerrar por encima de la bandera; detenerse bajo la bandera.",
  "Target ≈ pole height added to the break. Many flags never get there.": "Meta  Tómese la altura del poste añadido al descanso. Muchas banderas nunca llegan allí.",
  "Head and shoulders measured move to 90": "Cabeza y hombros medidos movimiento a 90",
