  "Flags and pennants usually ": "Banderas y colgantes generalmente",
  " it. Triangles can go either way — trade the break.": "Es. Los triángulos pueden ir de cualquier manera: cambiar el descanso.",
  "Head at 110, neckline at 100, close below neckline. Measured target?": "Cabeza a 110, escote a 100, cerca del escote. ¿Objetivo medido?",
  "Failed bull flag breakout": "Failed bull flag breakout",
  "Fake break": "Un descanso falso",
  "Missed target": "Objetivo perdido",
  "Same shape, failed follow-through. Patterns are common knowledge — expect stop runs when the break reverses.": "La misma forma, falló el seguimiento. Los patrones son el conocimiento común — esperar que se detenga cuando el descanso revierte.",
  "Patterns are common knowledge — expect stop runs.": "Los patrones son el conocimiento común — esperar que se detengan.",
  "Practice in Pattern Detective.": "Practica en Pattern Detective.",
  "Risk the plan, not the cartoon target.": "Arriesgue el plan, no el objetivo de dibujos animados.",
  "HTF uptrend already established — bias long.": "HTF uptrend ya establecido - sesgo largo.",
  "Confluence zone.": "Zona de confluencia.",
  "Pullback into prior support + rising MA area + Fib cluster. Multiple stories, one price.": "Retrocede en soporte previo + creciente área de MA + grupo de fibra. Varias historias, un precio.",
  "Trigger.": "Trigger.",
  "A candle pattern or break of a micro-level times the entry. Stop goes beyond the zone.": "Un patrón de vela o ruptura de un micro-nivel de la entrada. Parar va más allá de la zona.",
