  " tools pointing at the same idea (trend + level + trigger). Correlated copies of the same idea (five MAs) are not confluence.": "herramientas apuntando a la misma idea (trend + nivel + disparador). Las copias correlativas de la misma idea (cinco MA) no son confluencia.",
