  "Drill sizing in Risk Manager.": "Perforación en el Administrador de Riesgos.",
  "Mark a clear swing low to swing high — the impulse you care about.": "Marcar un swing claro bajo para oscilar alto — el impulso que te importa.",
  "Retracement map.": "Mapa de Retracement.",
  "38.2% and 61.8% are commonly watched pullback zones — habits, not laws.": "38.2% y 61,8% se observan comúnmente zonas de retroceso: hábitos, no leyes.",
  "Extensions (1.272, 1.618…) project take-profit ideas beyond the swing. Always pair with structure.": "Extensiones (1.272, 1.618...) proyecto tomar ideas de beneficio más allá del swing. Siempre con estructura.",
