  "Protect the account so you can keep learning.": "Protege la cuenta para que puedas seguir aprendiendo.",
  "Price falls into a level where buyers previously appeared.": "El precio cae en un nivel donde los compradores aparecieron anteriormente.",
  "Support holds.": "Sostenimiento.",
  "A second test finds buyers again. Two touches define a zone, not a single tick.": "Una segunda prueba encuentra compradores de nuevo. Dos toques definen una zona, no una sola garrapata.",
  "Break of the neckline.": "Rompe el escote.",
  "Resistance above gives way. Old resistance can flip to support on a retest.": "La resistencia arriba da paso. La vieja resistencia puede voltear para apoyar una prueba.",
  "Levels fail. Trade the reaction you planned — never assume a zone is sacred.": "Los niveles fallan. Cambiar la reacción que planeaste — nunca asumir una zona es sagrada.",
