  "Invalid": "Inválidos",
  "Price closes clearly through support on rising volume. Best next idea?": "El precio se cierra claramente mediante el apoyo al aumento del volumen. ¿La próxima idea?",
  "Treat the old support as potential resistance; wait for a reaction": "Tratar el antiguo apoyo como posible resistencia; esperar una reacción",
