  "Double size with no stop": "Doble tamaño sin parada",
  "Crowded levels can stop-run before reversing.": "Los niveles acumulados pueden parar de correr antes de invertir.",
  "Practice marking zones in Level Hunter.": "Zonas de marcado de práctica en el cazador de nivel.",
  "Combine with trend in later units.": "Combina con tendencia en unidades posteriores.",
  "Two higher lows give you a candidate rising line.": "Dos bajas superiores le dan una línea ascendente candidata.",
  "Third touch.": "Tercer toque.",
  "A third reaction adds confidence. Channels add a parallel on the other side.": "Una tercera reacción añade confianza. Los canales añaden un paralelo en el otro lado.",
  "Reaction": "Reacción",
  "A close beyond the line is a warning, not an automatic reverse. Wait for structure confirmation.": "Un cierre más allá de la línea es una advertencia, no un reverso automático. Espera a confirmación de la estructura.",
  "Connect swing lows in an uptrend (or swing highs in a downtrend). Need ": "Conecte oscilación baja en un uptrend (o columpios altos en un downtrend). Necesidad",
  " to draw; a ": "a dibujar; a",
  " validates.": "valida.",
  "A rising trend line has two touches only. Price dips to it. Best stance?": "Una línea de tendencia creciente sólo tiene dos toques. El precio se divierte. ¿La mejor postura?",
  "All-in: two points are sacred": "Todo en: dos puntos son sagrados",
  "Never use trend lines": "Nunca use líneas de tendencia",
  "Move the line so the dip looks perfect": "Mueva la línea para que el dip se vea perfecto",
  "Intraday wicks beyond a daily line often mean little.": "Las mechas de día más allá de una línea diaria a menudo significan poco.",
  "Combine line breaks with level breaks for better odds.": "Combina las rupturas de línea con las interrupciones de nivel para mejores probabilidades.",
  "Drill in Trendline Challenge.": "Perforación en el desafío de Trendline.",
  "A swing low forms. In an uptrend we expect the next low to hold above this one.": "Un swing bajo formas. En un ascenso esperamos que el próximo bajo se mantenga por encima de este.",
  "Higher high.": "Más alto.",
  "Buyers push a new high. Structure: higher high after a higher low.": "Los compradores empujan un nuevo alto. Estructura: más alto después de un bajo más alto.",
  "Another higher low. Until a lower low breaks the structure, the bias stays up.": "Otro bajo más alto. Hasta que un bajo nivel inferior rompe la estructura, el sesgo se mantiene arriba.",
  "Trends end when structure breaks: a decisive lower low after a series of higher lows (or the mirror for downtrends).": "Las tendencias terminan cuando la estructura se rompe: un nivel inferior decisivo después de una serie de bajos superiores (o el espejo para las torrentes).",
  "An ": "An",
  " prints higher highs and higher lows. A ": "imprime altos altos y bajos más altos. A",
  " prints lower highs and lower lows. Everything else is a ": "las impresiones bajan las alturas y bajan las bajas. Todo lo demás es un",
  " or transition.": "o transición.",
  "Real trends are jagged. Judge the sequence of swings, not perfection.": "Las tendencias reales están marcadas. Juzgue la secuencia de oscilaciones, no la perfección.",
  "Price makes a lower high then breaks the prior swing low on a closing basis. Best read?": "El precio hace que un alto inferior luego rompe el swing previo bajo en una base de cierre. ¿La mejor lectura?",
  "Uptrend structure is breaking — bias shifts down or to caution": "La estructura de uptrend está rompiendo - el sesgo cambia hacia abajo o para advertir",
  "Guaranteed new long-term bull market": "Garantizado nuevo mercado de toros a largo plazo",
  "Trends never end": "Las tendencias nunca terminan",
  "Ignore closes; only wicks matter": "Ignorar cierra; sólo importan las mechas",
  "Labels are approximate; two traders may mark different swings.": "Las etiquetas son aproximadas; dos traders pueden marcar diferentes oscilaciones.",
  "News gaps can smash structure overnight.": "Las brechas de noticias pueden romper la estructura durante la noche.",
  "Practise in Trend Spotter.": "Practicar en Trend Spotter.",
  "Coiling under resistance. Watch whether volume shrinks in the coil (interest resting).": "Coiling bajo resistencia. Vea si el volumen se encoge en la bobina (descansamiento del interés).",
  "Break on volume.": "Rompe el volumen.",
  "A real breakout usually expands participation. Thin breaks are suspects.": "Una ruptura real generalmente aumenta la participación. Las rupturas son sospechosos.",
  "Even strong volume can fail. Volume is evidence of participation — not a promise.": "Incluso el volumen fuerte puede fallar. El volumen es evidencia de participación, no una promesa.",
  "Confirmed break": "Rotura confirmada",
  "Volume expands on the break": "Volumen se expande en la rotura",
  "Close clears the level": "Cerrar aclara el nivel",
