  "A breakout closes above resistance on the lowest volume of the month. Best read?": "Una ruptura cierra sobre la resistencia en el volumen más bajo del mes. ¿La mejor lectura?",
  "Treat with suspicion — wait for confirmation": "Tratar con sospecha — esperar a confirmación",
  "Buy maximum size immediately": "Comprar el tamaño máximo inmediatamente",
  "Volume never matters": "Volumen nunca importa",
  "Short automatically every thin break": "Corto automáticamente cada fino descanso",
  "Climax volume can mark exhaustion as well as breakouts.": "El volumen Climax puede marcar el agotamiento, así como las interrupciones.",
  "Drill in Volume Verdict.": "Perforación en el Veredicto de Volumen.",
  "Always pair volume with price structure.": "Siempre par volumen con estructura de precio.",
  "Price has been falling: lower highs and lower lows. Sellers are in control.": "El precio ha estado bajando: bajos altos y bajos bajos bajos. Los vendedores están en control.",
  "A hammer prints: a long lower wick, a small body near the top. Buyers rejected the lows.": "Un martillo estampado: una larga mecha inferior, un pequeño cuerpo cerca de la parte superior. Los compradores rechazaron los bajos.",
  "Confirmation: the next candle closes above the hammer high. Entry, with the stop under the wick.": "Confirmación: la próxima vela se cierra por encima del martillo alto. Entrada, con la parada bajo la mecha.",
  "Target 2R": "Meta 2R",
  "Follow-through. It does not always work, which is why the stop is placed before the entry.": "Seguimiento. No siempre funciona, por lo que la parada se coloca antes de la entrada.",
  "A quiet market. Nothing to do yet.": "Un mercado tranquilo. Nada que hacer todavía.",
  "A fast, one-way rally on rising volume.": "Un rallye rápido y sencillo sobre el volumen creciente.",
  "A small, gentle drift against the pole on shrinking volume: buyers resting, not leaving.": "Una pequeña y suave deriva contra el polo sobre el volumen de reducción: los compradores descansan, no se van.",
  "The first close above the upper line is the entry; the stop goes under the flag low.": "El primer cierre por encima de la línea superior es la entrada; la parada baja bajo la bandera.",
  "The measured-move target: the pole’s height added to the breakout. Not every flag gets there.": "El objetivo de medición: la altura del poste se suma a la ruptura. No todas las banderas llegan allí.",
  "Developer preview": "Avance de desarrollador",
  "Not available here": "No disponible aquí",
  "This page only renders on a local development server.": "Esta página sólo se ejecuta en un servidor de desarrollo local.",
  "A tour of the lesson media helpers: figures with captions, key takeaways, animated chart stories, real examples with a textbook fallback, an interactive setup checklist and a side-by-side comparison.": "Un recorrido por los ayudantes de medios de lección: figuras con leyendas, tomas de llaves, historias de gráficos animados, ejemplos reales con un retroceso de libro de texto, una lista de verificación interactiva de configuración y una comparación de lado a lado.",
  "Figures and takeaways": "Figures and takeaways",
  "Diagrams sit in a figure with a numbered caption. Charts drawn with miniChart() or CandleChart go inside it unchanged.": "Los diagramas se sientan en una figura con una leyenda numerada. Los gráficos dibujados con miniChart() o CandleChart van dentro de él sin cambios.",
  "A hammer candle after a decline, with its confirmation level": "Una vela de martillo después de una caída, con su nivel de confirmación",
  "Context first: a hammer means something only after a decline.": "Contexto primero: un martillo significa algo sólo después de una caída.",
  "Wait for confirmation: a close above the hammer’s high.": "Espera la confirmación: un cierre por encima del alto del martillo.",
  "Put the stop under the wick before you enter.": "Pon la parada debajo de la mecha antes de entrar.",
  "storyStep: a hammer, step by step": "storyStep: un martillo, paso a paso",
  "The story plays frame by frame. Use the controls to pause, step or scrub.": "La historia juega marco por marco. Utilice los controles para pausar, paso o escrub.",
  "storyStep from a setup: a bull flag": "historiaPasa de una configuración: una bandera de toro",
  "Built from a setup’s meta: every line and marker sits on the exact candles the rule looked at.": "Construido desde el meta de una configuración: cada línea y marcador se sienta en las velas exactas que la regla miró.",
  "realExampleStep: the real thing": "realExampleStep: lo real",
  "A real hammer or bullish engulfing pattern from the market-data sample. When real data is unavailable, a textbook example is shown and clearly labelled.": "Un verdadero patrón de envolvimiento de martillo o bullish de la muestra de mercado-data. Cuando los datos reales no están disponibles, se muestra un ejemplo de libro de texto y se etiqueta claramente.",
  "Real examples are messier than textbook ones. Look for the same rules, not the same picture.": "Los ejemplos reales son más desordenados que los libros de texto. Busca las mismas reglas, no la misma imagen.",
  "checklistStep: is this a valid hammer?": "Lista de verificaciónStep: ¿es un martillo válido?",
  "Tick each rule. The chart marks what the rule looks at.": "Ata cada regla. El gráfico marca lo que la regla mira.",
  "It comes after a decline": "Viene después de una caída",
