  "faint dash-disclaimer": "desmayado",
  "How markets and orders work, what every candle is telling you, how trends and levels form, and how ": "Cómo funcionan los mercados y las órdenes, lo que cada vela te está diciendo, cómo se forman las tendencias y los niveles, y cómo",
  "moving averages and volume confirm a move. Nine short units, each with a game to lock it in, then a capstone that puts it all together.": "promedios móviles y volumen confirman un movimiento. Nueve unidades cortas, cada una con un juego para encerrarlo, luego un capstone que lo junta todo.",
  "Chart patterns, Fibonacci, indicators, multiple timeframes and breakouts, then the parts most traders ": "Patrones de gráficos, Fibonacci, indicadores, múltiples plazos y rupturas, luego las partes más comerciantes",
  "skip: confluence, risk and psychology. Turn a read of the chart into a plan with an entry, a stop and a target, and stick to it.": "saltar: confluencia, riesgo y psicología. Convierta una lectura de la tabla en un plan con una entrada, una parada y un objetivo, y se adhiera a ella.",
