  "Historical charts from real markets. The symbol and date stay hidden until you answer.": "Gráficos históricos de mercados reales. El símbolo y la fecha permanecen ocultos hasta que respondas.",
  "The arcade: practice, arcade and survival modes across every skill game. One free daily hook; the rest unlock with a plan.": "El arcade: práctica, arcade y modos de supervivencia a través de cada juego de habilidad. Un gancho diario gratis; el resto se desbloquea con un plan.",
  "Exact, rule-based setups: checklist, entry, stop and target, animated walk-throughs and real examples.": "Configuraciones exactas, basadas en reglas: lista de verificación, entrada, parada y objetivo, paseos animados y ejemplos reales.",
